-- Athena saved query (Product_B2C_Intl)
-- ID: ff1f91de-c1b3-433a-be40-0d65ddfa079f
-- Name: Student Viewed Throughput - Syed
-- Source: Syed Athena Saved Queries export
-- Prefer dataplatform MCP / Iceberg for runs; adjust only date params.
-- Default country: IND when applicable.

WITH loaded AS ( SELECT DISTINCT mri_session_id FROM user_interaction.ui_ux_events WHERE __time >= TIMESTAMP '2026-05-01 00:00:00' AND __time < TIMESTAMP '2026-05-02 00:00:00' AND event_group = 'ab_student_deal' AND header_bu = 'BUS' AND selected_country = 'India' AND event_src = 'Android' AND event_name = 'Student_Deal_section' AND TRIM(LOWER(event_value)) = 'loaded' ), sl AS ( SELECT DISTINCT mri_session_id FROM user_interaction.seat_layout_details WHERE __time >= TIMESTAMP '2026-05-01 00:00:00' AND __time < TIMESTAMP '2026-05-02 00:00:00' AND country = 'IND' ), confirm AS ( SELECT DISTINCT mri_session_id, tin FROM user_interaction.confirm_order_details WHERE __time >= TIMESTAMP '2026-05-01 00:00:00' AND __time < TIMESTAMP '2026-05-02 00:00:00' AND channel = 'MOBILE_APP' AND os = 'Android' AND country = 'IND' AND error_code = 'CONFIRMED' AND status_str = 'SUCCESS' AND tin IS NOT NULL AND tin NOT IN ('', 'null') ) SELECT COUNT(DISTINCT l.mri_session_id) AS loaded_sessions, COUNT(DISTINCT CASE WHEN sl.mri_session_id IS NOT NULL THEN l.mri_session_id END) AS loaded_then_sl_sessions, COUNT(DISTINCT CASE WHEN sl.mri_session_id IS NOT NULL AND c.mri_session_id IS NOT NULL THEN l.mri_session_id END) AS loaded_then_sl_then_confirm_sessions, COUNT(DISTINCT CASE WHEN sl.mri_session_id IS NOT NULL AND c.mri_session_id IS NOT NULL THEN c.tin END) AS loaded_then_sl_then_confirm_tins FROM loaded l LEFT JOIN sl ON l.mri_session_id = sl.mri_session_id LEFT JOIN confirm c ON l.mri_session_id = c.mri_session_id
